  function scaFor(cur){ return SCA[cur.type === 'm' ? cur.slug : cur.type === 'a' ? 'a:' + cur.slug : ''] || []; }

  // current page → {type, slug}
  function current(){
    var p = location.pathname;
    var m;
    if ((m = p.match(/\/tools\/algorithms\/([^\/]+)\.html/))) return {type:'a', slug:m[1], pre:'../../'};
    if ((m = p.match(/\/tools\/management\/([^\/]+)\.html/)))  return {type:'m', slug:m[1], pre:'../../'};
    if ((m = p.match(/\/cases\/([^\/]+)\.html/)))              return {type:'c', slug:m[1], pre:'../'};
    return null;
  }
  // find the REG entry whose field for this type === slug
  function lookup(cur){
    for (var k in REG){ if (REG[k][cur.type] === cur.slug) return REG[k]; }
    return null;
  }
  var DEF = {
    c:{icon:'📋', label:'Full case',           sub:'7-step reasoning walkthrough', path:function(p,s){return p+'cases/'+s+'.html';}},
    a:{icon:'🗺️', label:'Diagnostic algorithm', sub:'Visual triage + workup',       path:function(p,s){return p+'tools/algorithms/'+s+'.html';}},
    m:{icon:'💠', label:'Protocol',      sub:'Stepwise treatment pathway',   path:function(p,s){return p+'tools/management/'+s+'.html';}}
  };
  var ORDER = ['c','a','m'];
  // Slugs whose diagnostic algorithm has been RETIRED into the merged protocol page.
  // Never advertise the retired algorithm as a separate destination.
  var RETIRED_ALG = ['mscc','cauda-equina','svco','malignant-hypercalcaemia','terminal-haemorrhage','emergency-contraception','postnatal-disorders','malnutrition','sciatica','t2dm-ramadan','thyroid-pregnancy','acute-asthma','acute-copd','addisons-disease','aki','anogenital-warts','anxiety','asthma','bppv','ckd','cmpa','constipation-child','constipation-children','contraception','copd','cows-milk-allergy','crohns-disease','crohns-disease-flare','crohns-flare','diabetes-sick-day-rules','diabetes-unwell-insulin','diverticulitis','dka','dysmenorrhoea','erectile-dysfunction','fatty-liver','female-urinary-incontinence','gord','gout','hernia','high-cholesterol','hrt-menopause','hrt-prescribing','hypercholesterolaemia','hyperhidrosis','hypertension','hyperthyroidism','hypothyroidism','infertility','insomnia','iron-deficiency','iron-deficiency-anaemia','leg-cramps','low-mood','luts-men','male-luts','menieres','menieres-disease','menopause','menorrhagia','metabolic-syndrome','nausea-vomiting-pregnancy','neuropathic-pain','nvp','opioid-dependence','osa','osteoporosis','palliative-pain','pelvic-organ-prolapse','penile-disorders','premature-ejaculation','raynauds','restless-legs','sick-day-rules','snoring-osa','subclinical-hypothyroidism','t2dm','tia','type-2-diabetes','uc-flare','ulcerative-colitis','ulcerative-colitis-flare','undescended-testis','unwell-diabetes-insulin','urinary-incontinence-female','urticaria','precocious-puberty','otitis-media-effusion','subconjunctival-haemorrhage','vulvar-disorders','gestational-hyperglycaemia','recurrent-thrush','nail-disorders','recurrent-uti','hirsutism','uti-children','claudication','biliary-colic','anaphylaxis','screening-programmes','driving-diseases','surgical-problems-children'];

  function chipsFor(cur, entry){
    // Only cards/tracks matched by hand to THIS protocol or THIS algorithm (same condition).
    var out = { rx: [], audio: [] };
    if (cur.type !== 'm' && cur.type !== 'a') return out;
    ['rx','audio'].forEach(function(kind){
      var all = ITEMS[kind], seen = {};
      function add(typ, slug){
        if (!slug) return;
        Object.keys(all).forEach(function(id){
          if (!seen[id] && all[id][typ].indexOf(slug) !== -1){ seen[id] = 1; out[kind].push(id); }
        });
      }
      add(cur.type, cur.slug);
    });
    return out;
  }

  // Algorithms whose main protocol(s) differ from the REG topic match (Upload 120):
  // the strip on these algorithm pages shows these protocols instead of the REG one.
